-- Phase 3: income/expense ledger, category presets, receipts.

-- ---------------------------------------------------------------------------
-- categories: preset key (translated in the UI until the user renames it)
-- ---------------------------------------------------------------------------
alter table public.categories
  add column if not exists preset_key text;

