$$;
revoke all on function public.seed_default_categories(uuid, public.workspace_type) from public, anon, authenticated;

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  personal_id uuid;
  business_id uuid;
begin
  insert into public.workspaces (user_id, name, type) values (new.id, 'ផ្ទាល់ខ្លួន', 'PERSONAL')
    returning id into personal_id;
  insert into public.workspaces (user_id, name, type) values (new.id, 'អាជីវកម្ម', 'BUSINESS')
    returning id into business_id;
  perform public.seed_default_categories(personal_id, 'PERSONAL');
  perform public.seed_default_categories(business_id, 'BUSINESS');
  return new;
end;
$$;

-- Backfill workspaces created before this migration.
select public.seed_default_categories(w.id, w.type)
from public.workspaces w
where not exists (select 1 from public.categories c where c.workspace_id = w.id);

-- A transaction's category must match its kind (income vs expense).
create or replace function public.guard_transaction_category()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.category_id is not null and (
    new.type = 'TRANSFER' or not exists (
      select 1 from public.categories c where c.id = new.category_id and c.type::text = new.type::text
    )
  ) then
    raise exception 'category type does not match transaction type' using errcode = '22023';
  end if;
  return new;
end;
$$;

create or replace trigger transactions_category_guard
  before insert or update of category_id, type on public.transactions
  for each row execute function public.guard_transaction_category();

-- ---------------------------------------------------------------------------
-- Balances: income/expense may be entered in the other currency.
-- `amount`/`currency` are what the user typed; the wallet moves by the
-- amount converted at `exchange_rate` (KHR per 1 USD), rounded to the wallet
-- currency (cents for USD, whole riel for KHR). Transfers still require the
-- source wallet's currency and carry `to_amount` explicitly.
-- ---------------------------------------------------------------------------
create or replace function public.amount_in_wallet_currency(
  p_amount numeric, p_currency public.currency_code, p_rate numeric, p_wallet_currency public.currency_code
)
returns numeric
language sql
immutable
set search_path = ''
as $$
  select case
    when p_currency = p_wallet_currency then p_amount
    when p_currency = 'USD' then round(p_amount * p_rate, 0)
    else round(p_amount / p_rate, 2)
  end;
$$;

create or replace function public.adjust_wallet_balances(t public.transactions, direction integer)
returns void
language plpgsql
set search_path = ''
as $$
declare
  source_currency public.currency_code;
  target_currency public.currency_code;
  delta numeric;
begin
  select currency into source_currency from public.wallets_accounts where id = t.wallet_id;

  if t.type in ('INCOME', 'EXPENSE') then
    if t.currency <> source_currency and t.exchange_rate is null then
      raise exception 'exchange_rate is required when currency differs from the wallet' using errcode = '22023';
    end if;
    delta := public.amount_in_wallet_currency(t.amount, t.currency, t.exchange_rate, source_currency);
    if t.type = 'EXPENSE' then
      delta := -delta;
    end if;
    update public.wallets_accounts set balance = balance + direction * delta where id = t.wallet_id;
    return;
  end if;

  -- TRANSFER
  if direction > 0 then
    if source_currency is distinct from t.currency then
      raise exception 'transfer currency % does not match wallet currency %', t.currency, source_currency
        using errcode = '22023';
    end if;
    select currency into target_currency from public.wallets_accounts where id = t.to_wallet_id;
    if target_currency is distinct from t.currency and t.exchange_rate is null then
      raise exception 'cross-currency transfer requires exchange_rate' using errcode = '22023';
    end if;
  end if;
  update public.wallets_accounts set balance = balance - direction * t.amount where id = t.wallet_id;
  update public.wallets_accounts set balance = balance + direction * t.to_amount where id = t.to_wallet_id;
  if direction > 0 and exists (
    select 1 from public.wallets_accounts where id = t.wallet_id and balance < 0
  ) then
    raise exception 'insufficient_balance' using errcode = 'P0001';
  end if;
end;
$$;

create index if not exists transactions_workspace_type_date_idx on public.transactions (workspace_id, type, transaction_date desc);

-- ---------------------------------------------------------------------------
-- Receipts: private bucket, one folder per user: receipts/<auth.uid()>/<file>.
-- transactions.receipt_url stores the object path; the app shows it through
-- short-lived signed URLs.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('receipts', 'receipts', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

drop policy if exists receipts_select on storage.objects;
create policy receipts_select on storage.objects
  for select to authenticated
  using (bucket_id = 'receipts' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists receipts_insert on storage.objects;
create policy receipts_insert on storage.objects
  for insert to authenticated
  with check (bucket_id = 'receipts' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists receipts_delete on storage.objects;
create policy receipts_delete on storage.objects
  for delete to authenticated
  using (bucket_id = 'receipts' and (storage.foldername(name))[1] = (select auth.uid())::text);


-- ===========================================================================
-- 20261001030000_debts.sql
-- ===========================================================================

-- Phase 4: debt engine and repayments.
--
-- Money model: every repayment is ALSO a regular ledger transaction (EXPENSE
-- for a payable, INCOME for a receivable) linked through
-- debt_repayments.transaction_id and transactions.debt_id. Wallet balances are
-- therefore moved by the existing transactions_balance trigger, and repayments
-- appear in the ledger and cash flow. Repayments are recorded atomically with
-- public.record_debt_repayment(); deleting the transaction deletes the
-- repayment (cascade) and recomputes the debt.

do $$ begin create type public.interest_period as enum ('YEAR', 'MONTH'); exception when duplicate_object then null; end $$;

alter table public.debts
  add column if not exists note            text check (note is null or char_length(note) <= 500),
  add column if not exists interest_period public.interest_period not null default 'YEAR',
  add column if not exists start_date      date not null default current_date;

alter table public.transactions
  add column if not exists debt_id uuid,
  drop constraint if exists transactions_debt_id_workspace_id_fkey,
  add constraint transactions_debt_id_workspace_id_fkey
    foreign key (debt_id, workspace_id) references public.debts (id, workspace_id) on delete set null (debt_id);
create index if not exists transactions_debt_id_idx on public.transactions (debt_id);

alter table public.debt_repayments
  add column if not exists transaction_id uuid not null unique references public.transactions (id) on delete cascade;

-- Repayments are immutable (delete + re-record); amounts must stay in sync with
-- their transaction.
drop policy if exists debt_repayments_update on public.debt_repayments;

-- ---------------------------------------------------------------------------
-- Debt status / paid amount are always derived, never trusted from clients.
-- ---------------------------------------------------------------------------
create or replace function public.debt_status_for(p_total numeric, p_paid numeric, p_due date)
returns public.debt_status
language sql
stable
set search_path = ''
as $$
  select case
    when p_paid >= p_total then 'SETTLED'::public.debt_status
    when p_due is not null and p_due < current_date then 'OVERDUE'::public.debt_status
    when p_paid > 0 then 'PARTIALLY_PAID'::public.debt_status
    else 'ACTIVE'::public.debt_status
  end;
$$;

create or replace function public.on_debt_write()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.paid_amount := 0;
  else
    new.paid_amount := coalesce(
      (select sum(r.amount_paid) from public.debt_repayments r where r.debt_id = new.id), 0
    );
    if new.currency is distinct from old.currency and new.paid_amount > 0 then
      raise exception 'cannot change currency of a debt with repayments' using errcode = '22023';
    end if;
  end if;
  if new.total_amount < new.paid_amount then
    raise exception 'total_amount is below the amount already paid' using errcode = '22023';
  end if;
  new.status := public.debt_status_for(new.total_amount, new.paid_amount, new.due_date);
  return new;
end;
$$;

create or replace trigger debts_derive
  before insert or update on public.debts
  for each row execute function public.on_debt_write();

-- Repayment integrity: must point at a transaction of the same debt, wallet and amount.
create or replace function public.guard_debt_repayment()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not exists (
    select 1 from public.transactions t
    where t.id = new.transaction_id
      and t.debt_id = new.debt_id
      and t.wallet_id = new.wallet_id
      and t.amount = new.amount_paid
  ) then
    raise exception 'repayment does not match its transaction' using errcode = '22023';
  end if;
  return new;
end;
$$;

create or replace trigger debt_repayments_guard
  before insert on public.debt_repayments
  for each row execute function public.guard_debt_repayment();

-- Re-derive the debt after repayments change (touching the row fires debts_derive).
create or replace function public.on_debt_repayment_change()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  update public.debts set paid_amount = paid_amount
  where id = coalesce(new.debt_id, old.debt_id);
  return null;
end;
$$;

create or replace trigger debt_repayments_rederive
  after insert or delete on public.debt_repayments
  for each row execute function public.on_debt_repayment_change();

-- Ledger rows created for a repayment may only change their note / date /
-- category. Unlinking (debt_id -> null, done by the FK when a debt is deleted)
-- is allowed; the money history stays.
create or replace function public.guard_debt_transaction()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if old.debt_id is not null and (
    (new.amount, new.currency, new.wallet_id, new.type, new.exchange_rate)
      is distinct from (old.amount, old.currency, old.wallet_id, old.type, old.exchange_rate)
    or (new.debt_id is not null and new.debt_id <> old.debt_id)
  ) then
    raise exception 'debt repayment transactions are edited from the debt' using errcode = '22023';
  end if;
  return new;
end;
$$;

create or replace trigger transactions_debt_guard
  before update on public.transactions
  for each row execute function public.guard_debt_transaction();

-- ---------------------------------------------------------------------------
-- Repayment categories (presets), seeded for new workspaces and created on
-- demand for existing ones. Keep in sync with src/lib/categories/presets.ts.
-- ---------------------------------------------------------------------------
create or replace function public.ensure_preset_category(
  p_workspace_id uuid, p_key text, p_type public.category_type, p_icon text, p_color text, p_name text
)
returns uuid
language plpgsql
set search_path = ''
as $$
declare
  found_id uuid;
begin
  select id into found_id from public.categories
  where workspace_id = p_workspace_id and preset_key = p_key
  limit 1;
  if found_id is null then
    insert into public.categories (workspace_id, preset_key, type, icon, color, name)
    values (p_workspace_id, p_key, p_type, p_icon, p_color, p_name)
    returning id into found_id;
  end if;
  return found_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- record_debt_repayment: one atomic call for the ledger row + repayment row.
-- Runs as the caller, so RLS applies to every read and write.
-- `p_amount` is in the debt's currency; `p_exchange_rate` (KHR per 1 USD) is
-- required when the wallet uses the other currency.
-- ---------------------------------------------------------------------------
create or replace function public.record_debt_repayment(
  p_debt_id uuid,
  p_wallet_id uuid,
  p_amount numeric,
  p_exchange_rate numeric,
  p_payment_date timestamptz,
  p_note text
)
returns public.debt_repayments
language plpgsql
set search_path = ''
as $$
declare
  d public.debts;
  w public.wallets_accounts;
  category_id uuid;
  tx_id uuid;
  result public.debt_repayments;
begin
  select * into d from public.debts where id = p_debt_id for update;
  if not found then
    raise exception 'debt not found' using errcode = 'P0002';
  end if;
  select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = d.workspace_id;
  if not found then
    raise exception 'wallet not found in this workspace' using errcode = 'P0002';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'amount must be positive' using errcode = '22023';
  end if;
  if p_amount > d.total_amount - d.paid_amount then
    raise exception 'amount exceeds the remaining balance' using errcode = '22023';
  end if;

  if d.type = 'PAYABLE' then
    category_id := public.ensure_preset_category(d.workspace_id, 'debt_repayment', 'EXPENSE', 'hand-coins', '#64748b', 'សងបំណុល');
  else
    category_id := public.ensure_preset_category(d.workspace_id, 'debt_collection', 'INCOME', 'hand-coins', '#0ea5e9', 'ទទួលប្រាក់សងបំណុល');
  end if;

  insert into public.transactions (
    workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date, debt_id
  ) values (
    d.workspace_id, w.id, category_id, p_amount, d.currency,
    case when d.type = 'PAYABLE' then 'EXPENSE'::public.transaction_type else 'INCOME'::public.transaction_type end,
    case when w.currency = d.currency then null else p_exchange_rate end,
    coalesce(p_note, d.party_name), coalesce(p_payment_date, now()), d.id
  ) returning id into tx_id;

  insert into public.debt_repayments (debt_id, wallet_id, amount_paid, payment_date, note, transaction_id)
  values (d.id, w.id, p_amount, coalesce(p_payment_date, now()), p_note, tx_id)
  returning * into result;

  return result;
end;
$$;
revoke all on function public.record_debt_repayment(uuid, uuid, numeric, numeric, timestamptz, text) from public, anon;
grant execute on function public.record_debt_repayment(uuid, uuid, numeric, numeric, timestamptz, text) to authenticated;

create index if not exists debts_workspace_type_idx on public.debts (workspace_id, type, status);


-- ===========================================================================
-- 20261001040000_alerts_disbursement.sql
-- ===========================================================================

-- Phase 5: optional debt disbursement, Telegram settings, daily debt alerts.

-- ---------------------------------------------------------------------------
-- Optional money movement when a debt is created (once per debt):
--   PAYABLE    -> INCOME  "loan_received" into the wallet (borrowed funds)
--   RECEIVABLE -> EXPENSE "loan_given"   out of the wallet (lent funds)
-- The ledger row carries debt_id (so it is guarded like repayment rows) but
-- has no debt_repayments row, so it never counts as a repayment.
-- ---------------------------------------------------------------------------
alter table public.debts
  add column if not exists disbursement_transaction_id uuid unique references public.transactions (id) on delete set null;

create or replace function public.disburse_debt(
  p_debt_id uuid,
  p_wallet_id uuid,
  p_exchange_rate numeric,
  p_date timestamptz
)
returns public.transactions
language plpgsql
set search_path = ''
as $$
declare
  d public.debts;
  w public.wallets_accounts;
  category_id uuid;
  result public.transactions;
begin
  select * into d from public.debts where id = p_debt_id for update;
  if not found then
    raise exception 'debt not found' using errcode = 'P0002';
  end if;
  if d.disbursement_transaction_id is not null then
    raise exception 'debt already disbursed' using errcode = '22023';
  end if;
  select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = d.workspace_id;
  if not found then
    raise exception 'wallet not found in this workspace' using errcode = 'P0002';
  end if;

  if d.type = 'PAYABLE' then
    category_id := public.ensure_preset_category(d.workspace_id, 'loan_received', 'INCOME', 'landmark', '#6366f1', 'ប្រាក់ខ្ចីបានទទួល');
  else
    category_id := public.ensure_preset_category(d.workspace_id, 'loan_given', 'EXPENSE', 'hand-coins', '#f59e0b', 'ឱ្យគេខ្ចី');
  end if;

  insert into public.transactions (
    workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date, debt_id
  ) values (
    d.workspace_id, w.id, category_id, d.total_amount, d.currency,
    case when d.type = 'PAYABLE' then 'INCOME'::public.transaction_type else 'EXPENSE'::public.transaction_type end,
    case when w.currency = d.currency then null else p_exchange_rate end,
    d.party_name, coalesce(p_date, now()), d.id
  ) returning * into result;

  update public.debts set disbursement_transaction_id = result.id where id = d.id;
  return result;
end;
$$;
revoke all on function public.disburse_debt(uuid, uuid, numeric, timestamptz) from public, anon;
grant execute on function public.disburse_debt(uuid, uuid, numeric, timestamptz) to authenticated;

-- ---------------------------------------------------------------------------
-- Telegram settings (one bot per user). Owner-only via RLS. The token is the
-- user's own bot token; it is used only by run_debt_alerts() below.
-- ---------------------------------------------------------------------------
create table if not exists public.telegram_settings (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  bot_token  text not null check (bot_token ~ '^[0-9]{5,15}:[A-Za-z0-9_-]{30,64}$'),
  chat_id    text not null check (chat_id ~ '^(-?[0-9]{3,20}|@[A-Za-z0-9_]{5,32})$'),
  enabled    boolean not null default true,
  language   text not null default 'km' check (language in ('km', 'en')),
  updated_at timestamptz not null default now()
);
alter table public.telegram_settings enable row level security;
drop policy if exists telegram_settings_owner on public.telegram_settings;
create policy telegram_settings_owner on public.telegram_settings
  for all to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ---------------------------------------------------------------------------
-- Alert stages, mirrored by src/lib/alerts.ts. Ranges (not exact days) so a
-- missed cron run still fires the stage; each stage fires once per debt.
--   D7: 4-7 days left · D3: 1-3 days · D0: due today · OVERDUE: past due
-- ---------------------------------------------------------------------------
create or replace function public.debt_alert_stage(p_due date, p_today date)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_due is null then null
    when p_due - p_today between 4 and 7 then 'D7'
    when p_due - p_today between 1 and 3 then 'D3'
    when p_due - p_today = 0 then 'D0'
    when p_due - p_today < 0 then 'OVERDUE'
  end;
$$;

alter table public.notifications
  add column if not exists alert_key text,
  drop constraint if exists notifications_debt_alert_unique,
  add constraint notifications_debt_alert_unique unique (debt_id, alert_key);

create extension if not exists pg_net with schema extensions;
create extension if not exists pg_cron;

create or replace function public.format_money_text(p_amount numeric, p_currency public.currency_code)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_currency = 'USD' then '$' || to_char(p_amount, 'FM999,999,999,990.00')
    else to_char(p_amount, 'FM999,999,999,990') || '៛'
  end;
$$;

-- Runs daily from pg_cron (as the job owner, hence SECURITY DEFINER). Creates
-- one in-app notification per debt and stage, and sends it to the owner's
-- Telegram bot when configured. Not callable by clients.
create or replace function public.run_debt_alerts()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  today date := (now() at time zone 'Asia/Phnom_Penh')::date;
  r record;
  stage text;
  days integer;
  left_amount numeric;
  lang text;
  title text;
  body text;
  safe_name text;
  new_id uuid;
  sent integer := 0;
begin
  -- Keep stored statuses fresh (OVERDUE depends on the date).
  update public.debts set paid_amount = paid_amount
  where status in ('ACTIVE', 'PARTIALLY_PAID') and due_date < current_date;

  for r in
    select d.*, ws.user_id, ts.bot_token, ts.chat_id, ts.enabled as tg_enabled, ts.language as tg_language
    from public.debts d
    join public.workspaces ws on ws.id = d.workspace_id
    left join public.telegram_settings ts on ts.user_id = ws.user_id
    where d.status <> 'SETTLED' and d.due_date is not null
  loop
    stage := public.debt_alert_stage(r.due_date, today);
    continue when stage is null;

    days := r.due_date - today;
    left_amount := r.total_amount - r.paid_amount;
    lang := coalesce(r.tg_language, 'km');
    safe_name := replace(replace(replace(r.party_name, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');

    if lang = 'km' then
      title := case stage
        when 'OVERDUE' then '🔴 បំណុលហួសកំណត់'
        when 'D0' then '🔴 ដល់ថ្ងៃកំណត់ថ្ងៃនេះ'
        else '🟠 ជិតដល់ថ្ងៃកំណត់ (' || days || ' ថ្ងៃទៀត)'
      end;
      body := case when r.type = 'PAYABLE' then '📤 ត្រូវសងគេ: ' else '📥 គេជំពាក់យើង: ' end || safe_name
        || E'\n💰 នៅខ្វះ: ' || public.format_money_text(left_amount, r.currency)
        || ' / ' || public.format_money_text(r.total_amount, r.currency)
        || E'\n📅 ថ្ងៃកំណត់: ' || to_char(r.due_date, 'DD/MM/YYYY');
    else
      title := case stage
        when 'OVERDUE' then '🔴 Debt overdue'
        when 'D0' then '🔴 Due today'
        else '🟠 Due soon (' || days || ' days left)'
      end;
      body := case when r.type = 'PAYABLE' then '📤 I owe: ' else '📥 Owed to me: ' end || safe_name
        || E'\n💰 Remaining: ' || public.format_money_text(left_amount, r.currency)
        || ' of ' || public.format_money_text(r.total_amount, r.currency)
        || E'\n📅 Due: ' || to_char(r.due_date, 'DD/MM/YYYY');
    end if;

    new_id := null;
    insert into public.notifications (workspace_id, debt_id, title, message, type, alert_key, scheduled_at)
    values (r.workspace_id, r.id, title, body, 'DUE_DATE', stage, now())
    on conflict (debt_id, alert_key) do nothing
    returning id into new_id;

    if new_id is not null and r.bot_token is not null and r.tg_enabled then
      perform net.http_post(
        url := 'https://api.telegram.org/bot' || r.bot_token || '/sendMessage',
        body := jsonb_build_object(
          'chat_id', r.chat_id,
          'parse_mode', 'HTML',
          'text', '<b>' || title || E'</b>\n' || body || E'\n\n— លុយឆ្លាត · LuySmart'
        ),
        headers := '{"Content-Type": "application/json"}'::jsonb
      );
      sent := sent + 1;
    end if;
  end loop;
  return sent;
end;
$$;
revoke all on function public.run_debt_alerts() from public, anon, authenticated;

-- 01:00 UTC = 08:00 in Phnom Penh (guideline 4.3).
select cron.schedule('luysmart-debt-alerts', '0 1 * * *', $$select public.run_debt_alerts()$$);


-- ===========================================================================
-- 20261001050000_reset_my_data.sql
-- ===========================================================================

-- Phase 6: Danger Zone "Reset All Data" for signed-in users.
-- Deletes the caller's financial data in one transaction and re-seeds the
-- default categories; workspaces and the account itself are kept. Receipt
-- files in Storage are removed by the client (Storage API) beforehand.

create or replace function public.reset_my_data()
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  ws record;
begin
  if uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  -- Order matters: transactions reference wallets/categories/debts (NO ACTION),
  -- repayments cascade from transactions and debts.
  delete from public.notifications where workspace_id in (select id from public.workspaces where user_id = uid);
  delete from public.transactions where workspace_id in (select id from public.workspaces where user_id = uid);
  delete from public.debts where workspace_id in (select id from public.workspaces where user_id = uid);
  delete from public.wallets_accounts where workspace_id in (select id from public.workspaces where user_id = uid);
  delete from public.categories where workspace_id in (select id from public.workspaces where user_id = uid);
  delete from public.telegram_settings where user_id = uid;

  for ws in select id, type from public.workspaces where user_id = uid loop
    perform public.seed_default_categories(ws.id, ws.type);
  end loop;
end;
$$;
revoke all on function public.reset_my_data() from public, anon;
grant execute on function public.reset_my_data() to authenticated;


-- ===========================================================================
-- 20261001060000_reconcile_loans.sql
-- ===========================================================================

-- Phase 6: wallet reconciliation ("set the real balance").
-- Creates one adjustment ledger row for the difference between the recorded
-- and the actual balance, so the balance stays backed by transactions. The
-- wallet row is locked so a concurrent entry can't skew the difference.
-- Keep the preset names in sync with src/lib/categories/presets.ts.

create or replace function public.reconcile_wallet(p_wallet_id uuid, p_actual numeric, p_note text)
returns public.transactions
language plpgsql
set search_path = ''
as $$
declare
  w public.wallets_accounts;
  diff numeric;
  category_id uuid;
  result public.transactions;
begin
  select * into w from public.wallets_accounts where id = p_wallet_id for update;
  if not found then
    raise exception 'wallet not found' using errcode = 'P0002';
  end if;
  if p_actual is null then
    raise exception 'actual balance is required' using errcode = '22023';
  end if;

  diff := round(p_actual - w.balance, case when w.currency = 'KHR' then 0 else 2 end);
  if diff = 0 then
    return null;
  end if;

  if diff > 0 then
    category_id := public.ensure_preset_category(w.workspace_id, 'adjustment_in', 'INCOME', 'scale', '#64748b', 'កែតម្រូវសមតុល្យ (+)');
  else
    category_id := public.ensure_preset_category(w.workspace_id, 'adjustment_out', 'EXPENSE', 'scale', '#64748b', 'កែតម្រូវសមតុល្យ (−)');
  end if;

  insert into public.transactions (workspace_id, wallet_id, category_id, amount, currency, type, note, transaction_date)
  values (
    w.workspace_id, w.id, category_id, abs(diff), w.currency,
    case when diff > 0 then 'INCOME'::public.transaction_type else 'EXPENSE'::public.transaction_type end,
    p_note, now()
  )
  returning * into result;
  return result;
end;
$$;
revoke all on function public.reconcile_wallet(uuid, numeric, text) from public, anon;
grant execute on function public.reconcile_wallet(uuid, numeric, text) to authenticated;

-- ---------------------------------------------------------------------------
-- Loans saved from the calculator: the debt total is principal + interest,
-- but only the principal is received. disburse_debt() therefore takes an
-- optional amount (default: the full total, as before; must not exceed it).
-- ---------------------------------------------------------------------------
drop function if exists public.disburse_debt(uuid, uuid, numeric, timestamptz);

create or replace function public.disburse_debt(
  p_debt_id uuid,
  p_wallet_id uuid,
  p_exchange_rate numeric,
  p_date timestamptz,
  p_amount numeric default null
)
returns public.transactions
language plpgsql
set search_path = ''
as $$
declare
  d public.debts;
  w public.wallets_accounts;
  category_id uuid;
  moved numeric;
  result public.transactions;
begin
  select * into d from public.debts where id = p_debt_id for update;
  if not found then
    raise exception 'debt not found' using errcode = 'P0002';
  end if;
  if d.disbursement_transaction_id is not null then
    raise exception 'debt already disbursed' using errcode = '22023';
  end if;
  select * into w from public.wallets_accounts where id = p_wallet_id and workspace_id = d.workspace_id;
  if not found then
    raise exception 'wallet not found in this workspace' using errcode = 'P0002';
  end if;
  moved := coalesce(p_amount, d.total_amount);
  if moved <= 0 or moved > d.total_amount then
    raise exception 'disbursement amount must be between 0 and the debt total' using errcode = '22023';
  end if;

  if d.type = 'PAYABLE' then
    category_id := public.ensure_preset_category(d.workspace_id, 'loan_received', 'INCOME', 'landmark', '#6366f1', 'ប្រាក់ខ្ចីបានទទួល');
  else
    category_id := public.ensure_preset_category(d.workspace_id, 'loan_given', 'EXPENSE', 'hand-coins', '#f59e0b', 'ឱ្យគេខ្ចី');
  end if;

  insert into public.transactions (
    workspace_id, wallet_id, category_id, amount, currency, type, exchange_rate, note, transaction_date, debt_id
  ) values (
    d.workspace_id, w.id, category_id, moved, d.currency,
    case when d.type = 'PAYABLE' then 'INCOME'::public.transaction_type else 'EXPENSE'::public.transaction_type end,
    case when w.currency = d.currency then null else p_exchange_rate end,
    d.party_name, coalesce(p_date, now()), d.id
  ) returning * into result;

  update public.debts set disbursement_transaction_id = result.id where id = d.id;
  return result;
end;
$$;
revoke all on function public.disburse_debt(uuid, uuid, numeric, timestamptz, numeric) from public, anon;
grant execute on function public.disburse_debt(uuid, uuid, numeric, timestamptz, numeric) to authenticated;


-- ===========================================================================
-- 20261001070000_family_enums.sql
-- ===========================================================================

-- Phase 7 (part 1): new enum values. Kept in their own migration because a
-- value added with ALTER TYPE ... ADD VALUE can't be used in the transaction
-- that adds it.

-- Shared family / couple workspace (one per owner, created on demand).
alter type public.workspace_type add value if not exists 'FAMILY';

-- "Member X recorded an expense" alerts for the other members.
alter type public.notification_type add value if not exists 'ACTIVITY';


-- ===========================================================================
-- 20261001070100_family_sharing.sql
-- ===========================================================================

-- Phase 7: family / couple workspace sharing, attribution, realtime, budgets.
--
-- Access model (replaces "owner only" from the initial schema):
--   * workspace_members lists who can open a workspace and with which role.
--     OWNER  - the workspace's creator (workspaces.user_id); manages members
--     MEMBER - reads and writes the shared ledger
--     VIEWER - read only
--   * Personal and Business workspaces keep a single OWNER member. Only the
--     FAMILY workspace (one per owner, created on demand) can be shared, using
--     single-use 6-character invite codes.
--   * Wallets in a shared workspace are SHARED (anyone who can write may use
--     them) or PERSONAL (everyone sees them, only owner_id may move money).
--   * transactions / debts / debt_repayments record who created them.

do $$ begin create type public.workspace_role    as enum ('OWNER', 'MEMBER', 'VIEWER'); exception when duplicate_object then null; end $$;
do $$ begin create type public.wallet_visibility as enum ('SHARED', 'PERSONAL'); exception when duplicate_object then null; end $$;

-- ---------------------------------------------------------------------------
-- profiles: the display name shown as "កត់ដោយ៖ ..." to other members
-- ---------------------------------------------------------------------------
create table if not exists public.profiles (
  id           uuid primary key references auth.users (id) on delete cascade,
  display_name text not null check (char_length(display_name) between 1 and 40),
  updated_at   timestamptz not null default now()
);
alter table public.profiles enable row level security;

-- Name from the sign-in provider, else the e-mail's local part, else the phone's last digits.
create or replace function public.default_display_name(p_user_id uuid)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select left(coalesce(
    nullif(trim(u.raw_user_meta_data ->> 'full_name'), ''),
    nullif(trim(u.raw_user_meta_data ->> 'name'), ''),
    nullif(split_part(coalesce(u.email, ''), '@', 1), ''),
    case when u.phone is not null and u.phone <> '' then '•••' || right(u.phone, 3) end,
    'Member'
  ), 40)
  from auth.users u
  where u.id = p_user_id;
$$;
revoke all on function public.default_display_name(uuid) from public, anon, authenticated;

insert into public.profiles (id, display_name)
select u.id, public.default_display_name(u.id) from auth.users u
on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
-- workspace_members
-- ---------------------------------------------------------------------------
create table if not exists public.workspace_members (
  id           uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references public.workspaces (id) on delete cascade,
  user_id      uuid not null references public.profiles (id) on delete cascade,
  role         public.workspace_role not null default 'MEMBER',
  joined_at    timestamptz not null default now(),
  unique (workspace_id, user_id)
);
create index if not exists workspace_members_user_id_idx on public.workspace_members (user_id);
create unique index if not exists workspace_members_one_owner_idx on public.workspace_members (workspace_id) where role = 'OWNER';
alter table public.workspace_members enable row level security;

insert into public.workspace_members (workspace_id, user_id, role, joined_at)
select w.id, w.user_id, 'OWNER', w.created_at from public.workspaces w
on conflict (workspace_id, user_id) do nothing;

-- The creator of every workspace is its OWNER member.
create or replace function public.add_workspace_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, display_name)
  values (new.user_id, coalesce(public.default_display_name(new.user_id), 'Member'))
  on conflict (id) do nothing;
  insert into public.workspace_members (workspace_id, user_id, role)
  values (new.id, new.user_id, 'OWNER')
  on conflict (workspace_id, user_id) do nothing;
  return null;
end;
$$;

create or replace trigger workspaces_add_owner
  after insert on public.workspaces
  for each row execute function public.add_workspace_owner();

-- ---------------------------------------------------------------------------
-- Access helpers (SECURITY DEFINER avoids recursive RLS; they only ever
-- answer for the calling user).
-- ---------------------------------------------------------------------------
create or replace function public.is_workspace_member(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid())
  );
$$;

create or replace function public.can_write_workspace(ws_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.workspace_members m
    where m.workspace_id = ws_id and m.user_id = (select auth.uid()) and m.role in ('OWNER', 'MEMBER')
  );
$$;

-- True when the caller and p_user_id are both members of some workspace.
create or replace function public.shares_workspace_with(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.workspace_members mine
    join public.workspace_members theirs on theirs.workspace_id = mine.workspace_id
    where mine.user_id = (select auth.uid()) and theirs.user_id = p_user_id
  );
$$;

revoke all on function public.is_workspace_member(uuid) from public, anon;
revoke all on function public.can_write_workspace(uuid) from public, anon;
revoke all on function public.shares_workspace_with(uuid) from public, anon;
grant execute on function public.is_workspace_member(uuid) to authenticated;
grant execute on function public.can_write_workspace(uuid) to authenticated;
grant execute on function public.shares_workspace_with(uuid) to authenticated;

drop policy if exists profiles_select on public.profiles;
create policy profiles_select on public.profiles
  for select to authenticated
  using (id = (select auth.uid()) or public.shares_workspace_with(id));
drop policy if exists profiles_insert on public.profiles;
create policy profiles_insert on public.profiles
  for insert to authenticated with check (id = (select auth.uid()));
drop policy if exists profiles_update on public.profiles;
create policy profiles_update on public.profiles
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

drop policy if exists workspace_members_select on public.workspace_members;
create policy workspace_members_select on public.workspace_members
  for select to authenticated using (public.is_workspace_member(workspace_id));
-- The owner changes roles of others; nobody can become or stop being OWNER.
drop policy if exists workspace_members_update on public.workspace_members;
create policy workspace_members_update on public.workspace_members
  for update to authenticated
  using (public.owns_workspace(workspace_id) and role <> 'OWNER')
  with check (public.owns_workspace(workspace_id) and role in ('MEMBER', 'VIEWER'));
-- The owner removes members; members may leave. The owner row stays.
drop policy if exists workspace_members_delete on public.workspace_members;
create policy workspace_members_delete on public.workspace_members
  for delete to authenticated
  using (role <> 'OWNER' and (public.owns_workspace(workspace_id) or user_id = (select auth.uid())));

-- ---------------------------------------------------------------------------
-- Workspace-scoped RLS: members read, OWNER/MEMBER write.
-- ---------------------------------------------------------------------------
drop policy if exists workspaces_select on public.workspaces;
drop policy if exists workspaces_select on public.workspaces;
create policy workspaces_select on public.workspaces
  for select to authenticated using (public.is_workspace_member(id));

do $$
declare
  t text;
begin
  foreach t in array array['wallets_accounts', 'categories', 'transactions', 'debts', 'notifications']
  loop
    execute format('drop policy if exists %1$s_select on public.%1$I', t);
    execute format('drop policy if exists %1$s_insert on public.%1$I', t);
    execute format('drop policy if exists %1$s_update on public.%1$I', t);
    execute format('drop policy if exists %1$s_delete on public.%1$I', t);
  end loop;
  foreach t in array array['categories', 'transactions', 'debts']
  loop
    execute format(
      'create policy %1$s_select on public.%1$I for select to authenticated using (public.is_workspace_member(workspace_id))', t);
    execute format(
      'create policy %1$s_insert on public.%1$I for insert to authenticated with check (public.can_write_workspace(workspace_id))', t);
    execute format(
      'create policy %1$s_update on public.%1$I for update to authenticated using (public.can_write_workspace(workspace_id)) with check (public.can_write_workspace(workspace_id))', t);
    execute format(
      'create policy %1$s_delete on public.%1$I for delete to authenticated using (public.can_write_workspace(workspace_id))', t);
  end loop;
end
$$;

-- ---------------------------------------------------------------------------
-- Wallets: shared vs personal
-- ---------------------------------------------------------------------------
alter table public.wallets_accounts
  add column if not exists visibility public.wallet_visibility not null default 'SHARED',
  add column if not exists owner_id   uuid references auth.users (id) on delete set null default (auth.uid());

update public.wallets_accounts w set owner_id = ws.user_id
from public.workspaces ws
where ws.id = w.workspace_id and w.owner_id is null;

drop policy if exists wallets_accounts_select on public.wallets_accounts;
create policy wallets_accounts_select on public.wallets_accounts
  for select to authenticated using (public.is_workspace_member(workspace_id));
drop policy if exists wallets_accounts_insert on public.wallets_accounts;
create policy wallets_accounts_insert on public.wallets_accounts
  for insert to authenticated
  with check (public.can_write_workspace(workspace_id) and owner_id = (select auth.uid()));
-- Balance updates from the ledger trigger run as the caller, so this also
-- covers money movements (personal wallets are additionally guarded below).
drop policy if exists wallets_accounts_update on public.wallets_accounts;
create policy wallets_accounts_update on public.wallets_accounts
  for update to authenticated
  using (public.can_write_workspace(workspace_id) and (visibility = 'SHARED' or owner_id = (select auth.uid())))
  with check (public.can_write_workspace(workspace_id) and (visibility = 'SHARED' or owner_id = (select auth.uid())));
drop policy if exists wallets_accounts_delete on public.wallets_accounts;
create policy wallets_accounts_delete on public.wallets_accounts
  for delete to authenticated
  using (public.can_write_workspace(workspace_id) and (visibility = 'SHARED' or owner_id = (select auth.uid())));

-- owner_id is set once (the creator); only the owner may change visibility.
-- System code (member removal) sets luysmart.system for the transaction.
create or replace function public.guard_wallet_owner()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
begin
  if tg_op = 'INSERT' then
    if uid is not null then
      new.owner_id := uid;
    end if;
    return new;
  end if;
  new.owner_id := old.owner_id;
  if new.visibility is distinct from old.visibility
    and uid is not null
    and coalesce(current_setting('luysmart.system', true), '') <> 'on'
    and old.owner_id is distinct from uid then
    raise exception 'only the wallet owner can change its visibility' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace trigger wallets_accounts_owner_guard
  before insert or update on public.wallets_accounts
  for each row execute function public.guard_wallet_owner();

-- Money may only move through a PERSONAL wallet by its owner (inserts,
-- deletes, and edits of money fields; editing a note stays possible).
create or replace function public.guard_personal_wallet_use()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  ids uuid[] := '{}';
begin
  if uid is not null and coalesce(current_setting('luysmart.system', true), '') <> 'on' then
    if tg_op = 'UPDATE' then
      if (new.wallet_id, new.to_wallet_id, new.amount, new.to_amount, new.currency, new.type, new.exchange_rate)
          is not distinct from (old.wallet_id, old.to_wallet_id, old.amount, old.to_amount, old.currency, old.type, old.exchange_rate) then
        return new;
      end if;
    end if;
    if tg_op in ('INSERT', 'UPDATE') then
      ids := ids || new.wallet_id || new.to_wallet_id;
    end if;
    if tg_op in ('UPDATE', 'DELETE') then
      ids := ids || old.wallet_id || old.to_wallet_id;
    end if;
    if exists (
      select 1 from public.wallets_accounts w
      where w.id = any (ids) and w.visibility = 'PERSONAL' and w.owner_id is distinct from uid
    ) then
      raise exception 'personal_wallet: only its owner can use this wallet' using errcode = '42501';
    end if;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create or replace trigger transactions_personal_wallet_guard
  before insert or update or delete on public.transactions
  for each row execute function public.guard_personal_wallet_use();

-- ---------------------------------------------------------------------------
-- Attribution: who recorded a transaction, debt or repayment. The name is a
-- snapshot so the ledger still reads correctly after someone leaves.
-- ---------------------------------------------------------------------------
alter table public.transactions
  add column if not exists created_by      uuid references auth.users (id) on delete set null,
  add column if not exists created_by_name text check (created_by_name is null or char_length(created_by_name) <= 40);
alter table public.debts
  add column if not exists created_by      uuid references auth.users (id) on delete set null,
  add column if not exists created_by_name text check (created_by_name is null or char_length(created_by_name) <= 40);
alter table public.debt_repayments
  add column if not exists created_by      uuid references auth.users (id) on delete set null,
  add column if not exists created_by_name text check (created_by_name is null or char_length(created_by_name) <= 40);

-- Backfill (rows not yet attributed): everything so far was recorded by the workspace owner. Triggers
-- are off so balances and derived debt fields aren't recomputed.
alter table public.transactions disable trigger user;
update public.transactions t set created_by = ws.user_id, created_by_name = p.display_name
from public.workspaces ws join public.profiles p on p.id = ws.user_id
where ws.id = t.workspace_id and t.created_by is null;
alter table public.transactions enable trigger user;

alter table public.debts disable trigger user;
update public.debts d set created_by = ws.user_id, created_by_name = p.display_name
from public.workspaces ws join public.profiles p on p.id = ws.user_id
where ws.id = d.workspace_id and d.created_by is null;
alter table public.debts enable trigger user;

alter table public.debt_repayments disable trigger user;
update public.debt_repayments r set created_by = t.created_by, created_by_name = t.created_by_name
from public.transactions t
where t.id = r.transaction_id and r.created_by is null;
alter table public.debt_repayments enable trigger user;

create or replace function public.stamp_created_by()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce((select auth.uid()), new.created_by);
    new.created_by_name := coalesce(
      (select p.display_name from public.profiles p where p.id = new.created_by),
      new.created_by_name
    );
  else
    new.created_by := old.created_by;
    new.created_by_name := old.created_by_name;
  end if;
  return new;
end;
$$;

create or replace trigger transactions_stamp_created_by
  before insert or update on public.transactions
  for each row execute function public.stamp_created_by();
create or replace trigger debts_stamp_created_by
  before insert or update on public.debts
  for each row execute function public.stamp_created_by();
create or replace trigger debt_repayments_stamp_created_by
  before insert on public.debt_repayments
  for each row execute function public.stamp_created_by();

-- ---------------------------------------------------------------------------
-- debt_repayments: same membership rules through the debt and wallet.
-- ---------------------------------------------------------------------------
drop policy if exists debt_repayments_select on public.debt_repayments;
drop policy if exists debt_repayments_insert on public.debt_repayments;
drop policy if exists debt_repayments_delete on public.debt_repayments;
drop function if exists public.debt_repayment_same_workspace(uuid, uuid);

create or replace function public.debt_repayment_access(p_debt_id uuid, p_wallet_id uuid, p_write boolean)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.debts d
    join public.wallets_accounts w on w.workspace_id = d.workspace_id
    join public.workspace_members m on m.workspace_id = d.workspace_id
    where d.id = p_debt_id
      and w.id = p_wallet_id
      and m.user_id = (select auth.uid())
      and (not p_write or m.role in ('OWNER', 'MEMBER'))
  );
$$;
revoke all on function public.debt_repayment_access(uuid, uuid, boolean) from public, anon;
grant execute on function public.debt_repayment_access(uuid, uuid, boolean) to authenticated;

drop policy if exists debt_repayments_select on public.debt_repayments;
create policy debt_repayments_select on public.debt_repayments
  for select to authenticated using (public.debt_repayment_access(debt_id, wallet_id, false));
drop policy if exists debt_repayments_insert on public.debt_repayments;
create policy debt_repayments_insert on public.debt_repayments
  for insert to authenticated with check (public.debt_repayment_access(debt_id, wallet_id, true));
drop policy if exists debt_repayments_delete on public.debt_repayments;
create policy debt_repayments_delete on public.debt_repayments
  for delete to authenticated using (public.debt_repayment_access(debt_id, wallet_id, true));

-- ---------------------------------------------------------------------------
-- Notifications: optional recipient (null = everyone in the workspace).
-- ---------------------------------------------------------------------------
alter table public.notifications
  add column if not exists user_id        uuid references auth.users (id) on delete cascade,
  add column if not exists transaction_id uuid references public.transactions (id) on delete cascade,
  add column if not exists actor_name     text check (actor_name is null or char_length(actor_name) <= 40);
create index if not exists notifications_user_id_idx on public.notifications (user_id);
create index if not exists notifications_transaction_id_idx on public.notifications (transaction_id);

drop policy if exists notifications_select on public.notifications;
create policy notifications_select on public.notifications
  for select to authenticated
  using (public.is_workspace_member(workspace_id) and (user_id is null or user_id = (select auth.uid())));
drop policy if exists notifications_insert on public.notifications;
create policy notifications_insert on public.notifications
  for insert to authenticated
  with check (public.can_write_workspace(workspace_id) and (user_id is null or user_id = (select auth.uid())));
-- Any member may mark what they can see as read.
drop policy if exists notifications_update on public.notifications;
create policy notifications_update on public.notifications
  for update to authenticated
  using (public.is_workspace_member(workspace_id) and (user_id is null or user_id = (select auth.uid())))
  with check (public.is_workspace_member(workspace_id) and (user_id is null or user_id = (select auth.uid())));
drop policy if exists notifications_delete on public.notifications;
create policy notifications_delete on public.notifications
  for delete to authenticated
  using (public.can_write_workspace(workspace_id) and (user_id is null or user_id = (select auth.uid())));

-- ---------------------------------------------------------------------------
-- Family workspace + invitations
-- ---------------------------------------------------------------------------
-- Family uses the personal category presets.
create or replace function public.seed_default_categories(p_workspace_id uuid, p_type public.workspace_type)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_type in ('PERSONAL', 'FAMILY') then
    insert into public.categories (workspace_id, preset_key, type, icon, color, name) values
      (p_workspace_id, 'food',          'EXPENSE', 'utensils',       '#f97316', 'ម្ហូបអាហារ'),
      (p_workspace_id, 'transport',     'EXPENSE', 'bus',            '#0ea5e9', 'ការធ្វើដំណើរ'),
      (p_workspace_id, 'housing',       'EXPENSE', 'house',          '#8b5cf6', 'ផ្ទះ/ទឹកភ្លើង'),
      (p_workspace_id, 'shopping',      'EXPENSE', 'shopping-bag',   '#ec4899', 'ទិញឥវ៉ាន់'),
      (p_workspace_id, 'phone',         'EXPENSE', 'smartphone',     '#6366f1', 'ទូរស័ព្ទ/អ៊ីនធឺណិត'),
